public class RequestCounter
{
    private static readonly Dictionary<string, int> _counts = new();

    public bool TryRegister(string clientId, int limit)
    {
        if (!_counts.ContainsKey(clientId))
            _counts[clientId] = 0;

        if (_counts[clientId] >= limit)
            return false;

        _counts[clientId]++;
        return true;
    }

    public void Reset() => _counts.Clear();
}
