    {
        logger.LogInformation("Login attempt {@Request}", req);
        var user = await db.Users.SingleOrDefaultAsync(u => u.Email == req.Email, ct);
        if (user is null || !BCrypt.Verify(req.Password, user.PasswordHash))
        {
