public class ReminderService(AppDbContext db, IEmailSender mail) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromMinutes(1));
        while (await timer.WaitForNextTickAsync(ct))
        {
            var due = await db.Reminders.Where(r => !r.Sent && r.At <= DateTime.UtcNow)
                .ToListAsync(ct);
            foreach (var r in due) { await mail.SendAsync(r.Email, r.Text, ct); r.Sent = true; }
            await db.SaveChangesAsync(ct);
        }
    }
}

