private static bool IsActive(Subscription s)
{
    return !s.Cancelled
        && s.EndsAt > DateTime.UtcNow
        && s.Plan != "trial-expired";
}

public async Task RecalculateAsync(CancellationToken ct)
{
    var customerIds = await _db.Customers.Select(c => c.Id).ToListAsync(ct);

    await Parallel.ForEachAsync(customerIds,
        new ParallelOptions { MaxDegreeOfParallelism = 8, CancellationToken = ct },
        async (id, token) =>
        {
            var total = await _db.Orders
                .Where(o => o.CustomerId == id)
                .SumAsync(o => o.Total, token);
            var customer = await _db.Customers.FindAsync([id], token);
            customer!.Discount = total > 10_000 ? 0.1m : 0m;
        });

    await _db.SaveChangesAsync(ct);
}

