public class LateFeeService
{
    public decimal CalculateFee(int rentalId)
    {
        var repo = new SqlRentalRepository("Server=.;Database=Rentals;Trusted_Connection=True");
        var rental = repo.Get(rentalId);

        var daysLate = (DateTime.Now.Date - rental.DueDate.Date).Days;
        if (daysLate <= 0) return 0m;

        var fee = daysLate * 2.5m;
        new SmtpNotifier().Send(rental.CustomerEmail, $"Kara: {fee} zł");
        return Math.Min(fee, 100m);
    }
}

